{
  "doneWhen": "Player is at or adjacent to the ladder at (11,1) in the Mine.",
  "modes": [
    {
      "name": "navigate-to-ladder",
      "when": "always",
      "macro": "skill",
      "params": { "name": "go-to-ladder" }
    },
    {
      "name": "fight-adjacent-monster",
      "when": "a monster is within 1 tile and facing it",
      "actions": [
        { "press": ["ControllerX"], "ms": 100 }
      ]
    },
    {
      "name": "flee-if-crowded",
      "when": "two or more monsters within 2 tiles",
      "actions": [
        { "hold": ["DPadUp"], "ms": 300 }
      ]
    }
  ],
  "skills": [
    {
      "name": "go-to-ladder",
      "skill": "async (b) => { const r = await b.walkTo(11, 1, 'adjacent'); b.log('walkTo ladder: ' + JSON.stringify(r)); if (!r.ok) { await b.walkTo(11, 2, 'stand'); } }",
      "check": "async (b) => { const p = await b.body(); const ok = (Math.abs(p.x - 11) + Math.abs(p.y - 1)) <= 1; return { ok, detail: 'player at ' + p.x + ',' + p.y }; }"
    }
  ]
}
